from google.cloud import translate_v3 as translate
from typing import Generator
from speech_models import SpeechRecognitionResult # Assuming SpeechRecognitionResult is generic enough

def live_caption_translate(caption_results: Generator[SpeechRecognitionResult, None, None], target_language: str, project_id: str) -> Generator[str, None, None]:
    client = translate.TranslationServiceClient()
    parent = f"projects/{project_id}"

    for result in caption_results:
        if result.is_final and result.text:
            response = client.translate_text(
                request={
                    "parent": parent,
                    "contents": [result.text],
                    "target_language_code": target_language,
                }
            )
            for translation in response.translations:
                yield translation.translated_text

import google.generativeai as genai
from typing import Generator
from speech_models import SpeechRecognitionResult

def live_caption_safety(caption_results: Generator[SpeechRecognitionResult, None, None], google_api_key: str) -> Generator[dict, None, None]:
    genai.configure(api_key=google_api_key)
    model = genai.GenerativeModel('gemini-pro')

    for result in caption_results:
        if result.is_final and result.text:
            try:
                response = model.generate_content(
                    f"Analyze the following text for unsafe content: {result.text}. Respond with a JSON object indicating if the content is safe or not, and a reason if unsafe. Example: {{\"safe\": true}}" # Using a prompt for content safety analysis
                )
                # Assuming the model returns a text response that needs to be parsed as JSON
                # For a real implementation, you'd likely use a dedicated safety API or stricter parsing
                yield {"text": result.text, "safety_analysis": response.text}
            except Exception as e:
                yield {"text": result.text, "safety_analysis": {"error": str(e)}}

import google.generativeai as genai
from typing import Generator, List
from speech_models import SpeechRecognitionResult

def meeting_summary(caption_results: Generator[SpeechRecognitionResult, None, None], google_api_key: str, chunk_size: int = 5) -> Generator[str, None, None]:
    genai.configure(api_key=google_api_key)
    model = genai.GenerativeModel('gemini-pro')

    current_chunk_texts: List[str] = []
    for result in caption_results:
        if result.is_final and result.text:
            current_chunk_texts.append(result.text)
            if len(current_chunk_texts) >= chunk_size:
                text_to_summarize = " ".join(current_chunk_texts)
                try:
                    response = model.generate_content(
                        f"Summarize the following meeting transcript chunk: {text_to_summarize}"
                    )
                    yield response.text
                except Exception as e:
                    yield f"Error summarizing chunk: {e}"
                current_chunk_texts = []

    # Summarize any remaining text in the last chunk
    if current_chunk_texts:
        text_to_summarize = " ".join(current_chunk_texts)
        try:
            response = model.generate_content(
                f"Summarize the following meeting transcript chunk: {text_to_summarize}"
            )
            yield response.text
        except Exception as e:
            yield f"Error summarizing chunk: {e}"

import google.generativeai as genai
from typing import Generator, List, Dict, Any
from speech_models import SpeechRecognitionResult

def caption_embedding(caption_results: Generator[SpeechRecognitionResult, None, None], google_api_key: str, chunk_size: int = 5) -> Generator[Dict[str, Any], None, None]:
    genai.configure(api_key=google_api_key)

    current_chunk_texts: List[str] = []
    for result in caption_results:
        if result.is_final and result.text:
            current_chunk_texts.append(result.text)
            if len(current_chunk_texts) >= chunk_size:
                text_to_embed = " ".join(current_chunk_texts)
                try:
                    response = genai.embed_content(
                        model="models/embedding-001",
                        content=text_to_embed
                    )
                    yield {"text": text_to_embed, "embedding": response['embedding']}
                except Exception as e:
                    yield {"text": text_to_embed, "error": str(e)}
                current_chunk_texts = []

    # Embed any remaining text in the last chunk
    if current_chunk_texts:
        text_to_embed = " ".join(current_chunk_texts)
        try:
            response = genai.embed_content(
                model="models/embedding-001",
                content=text_to_embed
            )
            yield {"text": text_to_embed, "embedding": response['embedding']}
        except Exception as e:
            yield {"text": text_to_embed, "error": str(e)}
